#!/usr/bin/env python3
"""verify.py -- machine check of NOTE.md (groups generated by three prefix reversals).

G(n;m,k) = <r_n, r_m, r_k>, 2 <= k < m < n, r_i = reversal of the first i positions.
Checked for every n <= 101 (pure python; sympy cross-checks are optional):

  [paper]  m+k <= n-2 (full for n <= 60, a fixed sample for 61..101): G intransitive, or
           (n even only) transitive and imprimitive; n even, m+k = n-1: G intransitive or imprimitive.
  [line]   n = m+k+1, every parity: P = r_k r_n r_m has the closed form of Lemma 1,
           and the orbits are the classes {x = +-c mod g}, g = gcd(m+1, k+1)  (Theorem B(i)).
  [odd]    n odd on the line, g = 1: j-coordinates (Lemma 2), the block criterion (*_d) for
           every divisor d of n (Lemma 3), block systems exist iff (k+1) | m (Prop. 5), and then
           exactly for L = n/d with L | k+1 or (k+1) | L; the interval blocks (Lemma 6).
  [jordan] every primitive case contains a p-cycle, p prime <= n-3 (Jordan's theorem then
           gives G >= A_n without CFSG); A_n vs S_n by parity  (Theorem B(iv)).
  [final]  Theorem A and the classification of Theorem B for every case n <= 101.
  [sympy]  (optional) |G| for n <= 25 on the line; |G| = (2(k+1))^q 2q in the imprimitive case.
  [lemmaF] brute force: nonidentity collineations of PG(d-1,q) fix <= n/2 points,
           (d,q) in (2,4)* (2,8) (2,9) (2,16) (2,27) (3,2) (3,3) (3,4) (4,2); *=the exception.

Exit code 0 iff every check passes.  Runtime < 60 s, memory < 100 MB.
"""
import random
import sys
import time
from math import gcd

FAIL = []


def check(cond, msg):
    if not cond:
        FAIL.append(msg)
        if len(FAIL) < 20:
            print('FAIL:', msg)


# ---------------------------------------------------------------- permutations (0-based)
def rev(n, q):
    p = list(range(n))
    for j in range(q):
        p[j] = q - 1 - j
    return p


def mul(p, q):  # p after q
    return [p[x] for x in q]


def cycles(p):
    n = len(p)
    seen = [False] * n
    out = []
    for i in range(n):
        if not seen[i]:
            L = 0
            j = i
            while not seen[j]:
                seen[j] = True
                j = p[j]
                L += 1
            out.append(L)
    return out


def parity(p):
    return sum(c - 1 for c in cycles(p)) % 2


def power(p, e):
    n = len(p)
    r = list(range(n))
    b = p[:]
    while e:
        if e & 1:
            r = mul(b, r)
        b = mul(b, b)
        e >>= 1
    return r


def isprime(x):
    if x < 2:
        return False
    i = 2
    while i * i <= x:
        if x % i == 0:
            return False
        i += 1
    return True


def orbits(n, gens):
    par = list(range(n))

    def f(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    for g in gens:
        for x in range(n):
            a, b = f(x), f(g[x])
            if a != b:
                par[a] = b
    comp = {}
    for x in range(n):
        comp.setdefault(f(x), set()).add(x)
    return list(comp.values())


def min_block(n, gens, b):
    """finest G-invariant partition joining 0 and b; returns the class of 0"""
    par = list(range(n))

    def f(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    par[f(b)] = f(0)
    todo = [(0, b)]
    while todo:
        x, y = todo.pop()
        for g in gens:
            u, v = f(g[x]), f(g[y])
            if u != v:
                par[u] = v
                todo.append((u, v))
    r0 = f(0)
    return frozenset(x for x in range(n) if f(x) == r0)


def block_sizes(n, gens):
    """sizes of all nontrivial blocks containing 0 (transitive G)"""
    out = set()
    for b in range(1, n):
        B = min_block(n, gens, b)
        if len(B) < n:
            out.add(len(B))
    return out


def jordan_certificate(n, gens, seed, tries=6000):
    """product replacement; returns (p, element) with element^e a p-cycle, p prime <= n-3"""
    rng = random.Random(seed)
    X = [g[:] for g in gens] * 2
    acc = list(range(n))
    for _ in range(tries):
        i, j = rng.sample(range(len(X)), 2)
        X[i] = mul(X[i], X[j])
        acc = mul(acc, X[i])
        cl = cycles(acc)
        for L in set(cl):
            if L <= n - 3 and isprime(L) and cl.count(L) == 1 and all(c % L for c in cl if c != L):
                e = 1
                for c in cl:
                    if c != L:
                        e = e * c // gcd(e, c)
                h = power(acc, e)
                ch = sorted(c for c in cycles(h) if c > 1)
                if ch == [L]:
                    return L, acc
    return None


def gens_of(n, m, k):
    return [rev(n, n), rev(n, m), rev(n, k)]


# ---------------------------------------------------------------- the theorems
def theorem_A(n, m, k):
    """for m+k < n: True iff G = S_n"""
    return (n % 2 == 1 and m + k == n - 1 and gcd(m + 1, k + 1) == 1 and m % (k + 1) != 0
            and not (n % 4 == 1 and k % 4 == 0))


def theorem_B(n, m, k):
    """classification on the line n = m+k+1, n odd"""
    a, b = k + 1, m + 1
    if gcd(a, b) > 1:
        return 'intrans'
    if m % a == 0:
        return 'imprim'
    return 'A' if (n % 4 == 1 and k % 4 == 0) else 'S'


# ---------------------------------------------------------------- sections
def section_paper():
    t = time.time()
    cnt = 0
    triples = []
    for n in range(5, 61):
        for k in range(2, n):
            for m in range(k + 1, n):
                if m + k <= n - 2:
                    triples.append((n, m, k))
    rng = random.Random(2026)
    for _ in range(1500):
        n = rng.randrange(61, 102)
        k = rng.randrange(2, (n - 2) // 2)
        m = rng.randrange(k + 1, n - 1 - k)
        triples.append((n, m, k))
    imp = 0
    for (n, m, k) in triples:
        check(2 <= k < m and m + k <= n - 2, 'paper range %s' % ((n, m, k),))
        G = gens_of(n, m, k)
        if len(orbits(n, G)) == 1:
            # n odd: the orbit graph has <= n-2 edges, so this must not happen;
            # n even: a spanning tree is possible, then the 2-colouring gives blocks
            check(n % 2 == 0 and len(block_sizes(n, G)) > 0, 'paper < S_n %s' % ((n, m, k),))
            imp += 1
        cnt += 1
    ev = 0
    for n in range(6, 102, 2):
        for k in range(2, n):
            m = n - 1 - k
            if not k < m:
                continue
            G = gens_of(n, m, k)
            if len(orbits(n, G)) == 1:
                check(len(block_sizes(n, G)) > 0, 'paper even imprim %s' % ((n, m, k),))
            ev += 1
    print('[paper]  m+k<=n-2: %d triples < S_n (%d of them transitive, all n even, imprimitive);'
          ' n even, m+k=n-1: %d triples < S_n  (%.1fs)' % (cnt, imp, ev, time.time() - t))


def section_line():
    t = time.time()
    cnt = 0
    for n in range(5, 102):
        for k in range(2, n):
            m = n - 1 - k
            if not k < m:
                continue
            a, b = k + 1, m + 1
            G = gens_of(n, m, k)
            rn, rm, rk = G
            P = mul(rk, mul(rn, rm))
            # Lemma 1 closed form (1-based x): x+a (x<=m), m+1 -> a, x-b (x>=m+2)
            want = [0] * n
            for x in range(1, n + 1):
                y = x + a if x <= m else (a if x == m + 1 else x - b)
                want[x - 1] = y - 1
            check(P == want, 'Lemma1 P %s' % ((n, m, k),))
            # Theorem B(i): orbits are {x = +-c mod g}
            g = gcd(a, b)
            orb = sorted(sorted(o) for o in orbits(n, G))
            cls = {}
            for x in range(1, n + 1):
                c = x % g
                cls.setdefault(min(c, (g - c) % g), []).append(x - 1)
            check(orb == sorted(cls.values()), 'orbits %s' % ((n, m, k),))
            check(len(orb) == g // 2 + 1, 'orbit count %s' % ((n, m, k),))
            cnt += 1
    print('[line]   %d triples on n=m+k+1 (n<=101): Lemma 1 and orbit formula OK  (%.1fs)'
          % (cnt, time.time() - t))


def section_odd():
    t = time.time()
    stats = {'intrans': 0, 'imprim': 0, 'A': 0, 'S': 0}
    primes = {}
    gen_count = {}
    for n in range(7, 102, 2):
        N = n + 1
        for k in range(2, n):
            m = n - 1 - k
            if not k < m:
                continue
            a, b = k + 1, m + 1
            G = gens_of(n, m, k)
            rn, rm, rk = G
            pred = theorem_B(n, m, k)
            if gcd(a, b) > 1:
                check(len(orbits(n, G)) > 1, 'intrans %s' % ((n, m, k),))
                stats['intrans'] += 1
                check(pred == 'intrans', 'pred intrans %s' % ((n, m, k),))
                check(not theorem_A(n, m, k), 'thmA intrans %s' % ((n, m, k),))
                continue
            th = pow(a, -1, N)
            phi = [(th * x) % N for x in range(1, n + 1)]          # x (1-based) -> j
            check(sorted(phi) == list(range(1, n + 1)), 'phi bij %s' % ((n, m, k),))
            P = mul(rk, mul(rn, rm))
            inv = [0] * (n + 1)
            for x in range(1, n + 1):
                inv[phi[x - 1]] = x
            # Lemma 2: P is the shift, r_n is j -> n+1-j, r_k is j -> n+2-j on E
            E = set(phi[x - 1] for x in range(1, k + 1))
            check(E == set(-(-s * N // a) for s in range(1, a)), 'E Beatty %s' % ((n, m, k),))
            for j in range(1, n + 1):
                x = inv[j]
                check(phi[P[x - 1]] == (j % n) + 1, 'P shift %s' % ((n, m, k),))
                check(phi[rn[x - 1]] == n + 1 - j, 'rn refl %s' % ((n, m, k),))
                check(phi[rk[x - 1]] == ((n + 2 - j) if j in E else j), 'rk %s' % ((n, m, k),))
            # Lemma 3 / Prop 4: (*_d) for every divisor d, compared with block computation
            star = set()
            for d in range(2, n):
                if n % d:
                    continue
                ok = True
                for c in range(d):
                    if c == 1 % d:
                        continue
                    C = [j for j in range(1, n + 1) if j % d == c]
                    inside = sum(1 for j in C if j in E)
                    if 0 < inside < len(C):
                        ok = False
                        break
                # direct: does r_k preserve the mod-d partition?
                direct = all(len(set(phi[rk[inv[j] - 1]] % d for j in range(1, n + 1) if j % d == c)) == 1
                             for c in range(d))
                check(ok == direct, '(*_d) %s d=%d' % ((n, m, k), d))
                if ok:
                    star.add(n // d)
            bs = block_sizes(n, G)
            check(bs == star, 'blocks %s %s %s' % ((n, m, k), bs, star))
            if m % a == 0:
                check(bs == set(L for L in range(2, n) if n % L == 0 and (a % L == 0 or L % a == 0)),
                      'block sizes formula %s' % ((n, m, k),))
                # Lemma 6: intervals of length a are blocks
                blocks = [set(range(i, i + a)) for i in range(0, n, a)]
                for gp in G:
                    for B in blocks:
                        check(set(gp[x] for x in B) in blocks, 'interval block %s' % ((n, m, k),))
                stats['imprim'] += 1
                check(pred == 'imprim', 'pred imprim %s' % ((n, m, k),))
                check(not theorem_A(n, m, k), 'thmA imprim %s' % ((n, m, k),))
                continue
            check(len(bs) == 0, 'primitive %s' % ((n, m, k),))
            cert = None
            for seed in range(1, 6):
                cert = jordan_certificate(n, G, seed)
                if cert:
                    break
            check(cert is not None, 'jordan %s' % ((n, m, k),))
            if cert:
                primes[cert[0]] = primes.get(cert[0], 0) + 1
            odd = any(parity(gp) for gp in G)
            got = 'S' if odd else 'A'
            stats[got] += 1
            check(got == pred, 'pred A/S %s' % ((n, m, k),))
            check(theorem_A(n, m, k) == (got == 'S'), 'thmA %s' % ((n, m, k),))
            if got == 'S':
                gen_count[n] = gen_count.get(n, 0) + 1
    print('[odd]    n odd <= 101 on the line: %s  (%.1fs)' % (stats, time.time() - t))
    print('[jordan] primes used in certificates: %s' % dict(sorted(primes.items())))
    return stats, gen_count


def section_sympy():
    try:
        from sympy.combinatorics import Permutation, PermutationGroup
    except Exception:
        print('[sympy]  skipped (sympy not importable)')
        return
    from math import factorial
    t = time.time()
    c1 = c2 = 0
    for n in range(7, 26):
        for k in range(2, n):
            m = n - 1 - k
            if not k < m:
                continue
            o = PermutationGroup([Permutation(g) for g in gens_of(n, m, k)]).order()
            if n % 2:
                exp = {'S': factorial(n), 'A': factorial(n) // 2}.get(theorem_B(n, m, k))
                if exp:
                    check(o == exp, 'sympy order %s' % ((n, m, k),))
                else:
                    check(o < factorial(n) // 2, 'sympy small %s' % ((n, m, k),))
            else:
                check(o < factorial(n), 'sympy even %s' % ((n, m, k),))
            c1 += 1
    for n in range(9, 52, 2):
        for k in range(2, n, 2):
            m = n - 1 - k
            a = k + 1
            if k < m and gcd(a, m + 1) == 1 and m % a == 0:
                q = n // a
                o = PermutationGroup([Permutation(g) for g in gens_of(n, m, k)]).order()
                check(o == (2 * a) ** q * 2 * q, 'wreath order %s' % ((n, m, k),))
                c2 += 1
    print('[sympy]  %d orders on the line (n<=25) and %d wreath orders (n<=51) OK  (%.1fs)'
          % (c1, c2, time.time() - t))


# ---------------------------------------------------------------- Lemma F brute force
def gf(p, e):
    """GF(p^e): elements 0..q-1 (base-p digits = coefficients); returns q, add, mul, frob tables"""
    irr = {(2, 1): [1, 0], (3, 1): [1, 0], (2, 2): [1, 1, 1], (2, 3): [1, 1, 0, 1],
           (3, 2): [1, 0, 1], (2, 4): [1, 1, 0, 0, 1], (3, 3): [1, 2, 0, 1]}[(p, e)]
    q = p ** e

    def dig(x):
        return [(x // p ** i) % p for i in range(e)]

    def num(v):
        return sum(c * p ** i for i, c in enumerate(v))
    add = [[num([(u + v) % p for u, v in zip(dig(x), dig(y))]) for y in range(q)] for x in range(q)]

    def pmul(x, y):
        a, b = dig(x), dig(y)
        r = [0] * (2 * e)
        for i in range(e):
            for j in range(e):
                r[i + j] = (r[i + j] + a[i] * b[j]) % p
        for deg in range(2 * e - 1, e - 1, -1):   # reduce by the monic irreducible of degree e
            c = r[deg]
            if c:
                for i in range(e + 1):
                    r[deg - e + i] = (r[deg - e + i] - c * irr[i]) % p
        return num(r[:e])
    mt = [[pmul(x, y) for y in range(q)] for x in range(q)]
    frob = [0] * q
    for x in range(q):
        y = 1
        for _ in range(p):
            y = mt[y][x]
        frob[x] = y
    return q, add, mt, frob


def lemmaF(d, p, e, only_semilinear=False):
    q, add, mt, frob = gf(p, e)
    inv = [0] * q
    for x in range(1, q):
        for y in range(1, q):
            if mt[x][y] == 1:
                inv[x] = y
    pts = []
    index = {}
    for code in range(1, q ** d):
        v = tuple((code // q ** i) % q for i in range(d))
        lead = next(c for c in v if c)
        w = tuple(mt[inv[lead]][c] for c in v)
        if w not in index:
            index[w] = len(pts)
            pts.append(w)
        index[v] = index[w]
    n = len(pts)
    best = 0
    sig = []
    fv = list(pts)
    for _ in range(e):
        sig.append(fv)
        fv = [tuple(frob[c] for c in v) for v in fv]
    rng_i = range(1, e) if only_semilinear else range(e)
    for code in range(q ** (d * d)):
        A = [(code // q ** i) % q for i in range(d * d)]
        lead = next((c for c in A if c), 0)
        if lead != 1:
            continue
        rows = [A[r * d:(r + 1) * d] for r in range(d)]
        for i in rng_i:
            fix = 0
            okA = True
            for t, w in enumerate(sig[i]):
                img = []
                for row in rows:
                    s = 0
                    for c in range(d):
                        s = add[s][mt[row[c]][w[c]]]
                    img.append(s)
                img = tuple(img)
                if not any(img):
                    okA = False
                    break
                if index[img] == t:
                    fix += 1
            if not okA:
                break
            if fix < n:
                best = max(best, fix)
    return n, best


def section_lemmaF():
    t = time.time()
    rows = []
    for (d, p, e, semi) in [(2, 2, 2, False), (2, 2, 3, False), (2, 3, 2, False), (2, 2, 4, False),
                            (2, 3, 3, False), (3, 2, 1, False), (3, 3, 1, False), (3, 2, 2, True),
                            (4, 2, 1, False)]:
        n, best = lemmaF(d, p, e, semi)
        q = p ** e
        rows.append('PG(%d,%d) n=%d max=%d%s' % (d - 1, q, n, best, ' (semilinear)' if semi else ''))
        if (d, q) == (2, 4):
            check(best == 3, 'lemmaF exception (2,4)')
        else:
            check(2 * best <= n, 'lemmaF %s' % ((d, q),))
    print('[lemmaF] ' + '; '.join(rows) + '  (%.1fs)' % (time.time() - t))


def main():
    t0 = time.time()
    section_paper()
    section_line()
    stats, gen_count = section_odd()
    section_sympy()
    section_lemmaF()
    print('[final]  S_n-generating triples below the diagonal, n<=101: %d (first n: %s)'
          % (sum(gen_count.values()), sorted(gen_count.items())[:8]))
    print('total %.1fs; %s' % (time.time() - t0, 'ALL CHECKS PASSED' if not FAIL else '%d FAILURES' % len(FAIL)))
    sys.exit(1 if FAIL else 0)


if __name__ == '__main__':
    main()
